#!/usr/bin/env node
/**
 * Static check for the distribution bundle and its generated patch.
 *
 * usage: node scripts/check-dataops-bundle.mjs
 */
import { spawnSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

const root = resolve(import.meta.dirname, '..')
const read = path => readFileSync(join(root, path), 'utf8')
const json = path => JSON.parse(read(path))
const failures = []
const check = (ok, message) => { if (!ok) failures.push(message) }
const bundle = json('packages/dataops-bundle/package.json')
const preset = json('packages/dataops-preset/package.json')
const local = {
  '@dataops/dsh-dataops-tools': json('packages/dataops-tools/package.json'),
  '@dataops/dsh-dataops-client': json('packages/dataops-client/package.json'),
  '@dataops/dsh-dataops-brand': json('packages/dataops-brand/package.json')
}
const engineRange = '>=0.2.1-rc.2 <0.3.0'

check(bundle.name === '@dataops/dsh-dataops-bundle', 'bundle package name mismatch')
check(bundle.version === '0.1.0', 'bundle version must be 0.1.0')
check(bundle.private !== true, 'bundle must be publishable (no private: true)')
check(bundle.license === 'UNLICENSED', 'bundle license must be UNLICENSED')
check(Boolean(bundle.repository), 'bundle repository missing')
check(bundle.dsh && bundle.dsh.bundle && bundle.dsh.bundle.patch === './cordis.patch.yml', 'bundle dsh.bundle.patch mismatch')
check(bundle.engines && bundle.engines.dsh === engineRange, 'bundle engines.dsh mismatch')
check(Array.isArray(bundle.files) && bundle.files.includes('cordis.patch.yml'), 'bundle files must include cordis.patch.yml')
check(Array.isArray(bundle.files) && bundle.files.includes('README.md'), 'bundle files must include README.md')
check(Array.isArray(bundle.files) && bundle.files.includes('THIRD_PARTY_NOTICES.md'), 'bundle files must include THIRD_PARTY_NOTICES.md')

for (const [name, pkg] of Object.entries(local)) {
  check(bundle.dependencies && bundle.dependencies[name] === '0.1.0', 'bundle dependency must be exact 0.1.0: ' + name)
  check(pkg.version === '0.1.0', 'local package version must be 0.1.0: ' + name)
  check(pkg.engines && pkg.engines.dsh === engineRange, 'package engines.dsh mismatch: ' + name)
  check(pkg.license === 'UNLICENSED', 'package license must be UNLICENSED: ' + name)
  check(pkg.private !== true, 'package must be publishable (no private: true): ' + name)
}
check(!bundle.dependencies || bundle.dependencies['@dataops/dsh-dataops-preset'] === undefined, 'preset must be a source fragment, not a runtime dependency')
check(preset.version === '0.1.0', 'preset version must be 0.1.0')
check(preset.engines && preset.engines.dsh === engineRange, 'preset engines.dsh mismatch')
check(preset.license === 'UNLICENSED', 'preset license must be UNLICENSED')
check(preset.private !== true, 'preset must be publishable (no private: true)')

const generatedPath = 'packages/dataops-bundle/cordis.patch.yml'
check(existsSync(join(root, generatedPath)), 'generated bundle patch missing; run build-dataops-bundle')

if (existsSync(join(root, generatedPath))) {
  const patch = read(generatedPath)
  for (const token of [
    "name: '@dataops/dsh-dataops-tools'",
    "name: '@dataops/dsh-dataops-brand'",
    "name: '@dataops/dsh-dataops-client'",
    "name: '@deepseek-ai/dsh-agent-preset'",
    'id: preset-dataops-dev',
    'id: ui-brand-official',
    'default: dataops-dev',
    'disabled: true'
  ]) check(patch.includes(token), 'generated patch missing: ' + token)
  check(patch.includes('GENERATED by scripts/build-dataops-bundle.mjs'), 'generated patch missing header')
}

const build = spawnSync(process.execPath, [join(root, 'scripts', 'build-dataops-bundle.mjs'), '--check'], { encoding: 'utf8' })
check(build.status === 0, 'generated patch is stale: ' + (build.stderr || build.stdout || '').trim())

if (failures.length) {
  console.error('dataops bundle: FAIL')
  for (const failure of failures) console.error(' - ' + failure)
  process.exit(1)
}
console.log('dataops bundle ok: ' + bundle.name + '@' + bundle.version + ' + generated patch')
